INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (61, '腓特烈·巴巴罗萨', 'Frederick Barbarossa', '约1122—1190', '中世纪', '神圣罗马', '皇帝', ARRAY['帝王', '中世纪', '军事'], '神圣罗马帝国皇帝，以红胡子闻名。他数度远征意大利并参与十字军东征，是中世纪德意志王权的象征。', '十字军医官', '', 'assets/figures/barbarossa.jpg', ARRAY['12-01', '03-09'], ARRAY['诞辰 · 约1122年', '加冕 · 1152年3月9日'], ARRAY['birth', 'throne'], '东征路上伤员归你照看，绷带是你一匹匹裁的。', ARRAY['十字军医官', '渡河向导'], ARRAY['东征路上伤员归你照看，绷带是你一匹匹裁的。', '翻过阿尔卑斯山，是你替他带的路，雪深没膝也没迷向。']),
  (62, '彼得大帝', 'Peter the Great', '1672—1725', '17—18世纪', '俄国', '沙皇', ARRAY['帝王', '俄国', '改革'], '俄国沙皇，推行全面西化改革。他迁都圣彼得堡、建立海军、整顿行政，使俄国步入欧洲强国之列。', '造船工友', '', 'assets/figures/peter.jpg', ARRAY['06-09', '01-29'], ARRAY['诞辰 · 1672年6月9日', '独掌大权 · 1696年1月29日'], ARRAY['birth', 'event'], '他在造船厂当学徒时，和你抡的是同一把斧。', ARRAY['造船工友', '使团翻译'], ARRAY['他在造船厂当学徒时，和你抡的是同一把斧。', '出使西欧那趟，你是他身边唯一能说几国话的翻译。']),
  (63, '腓特烈大帝', 'Frederick the Great', '1712—1786', '18世纪', '普鲁士', '国王', ARRAY['帝王', '普鲁士', '启蒙'], '普鲁士国王，启蒙君主的代表。他扩充领土、改革军制与法律，又精通长笛与哲学，是开明专制的典型。', '长笛搭档', '', 'assets/figures/frederick2.jpg', ARRAY['01-24', '05-31'], ARRAY['诞辰 · 1712年1月24日', '继位 · 1740年5月31日'], ARRAY['birth', 'throne'], '他夜里吹长笛，你是唯一的听众，还替他记过谱。', ARRAY['长笛搭档', '军需书记'], ARRAY['他夜里吹长笛，你是唯一的听众，还替他记过谱。', '战时补给的单子，落款是你的名，他只管签字。']),
  (64, '征服者威廉', 'William the Conqueror', '约1028—1087', '中世纪', '英格兰', '国王', ARRAY['帝王', '英格兰', '军事'], '诺曼底公爵，1066年征服英格兰，建立诺曼王朝。他编制《末日审判书》，重塑了英格兰的政治与土地结构。', '渡海船工', '', 'assets/figures/william1.jpg', ARRAY['10-14', '12-25'], ARRAY['黑斯廷斯之战 · 1066年10月14日', '加冕 · 1066年12月25日'], ARRAY['event', 'throne'], '1066年那支舰队，有你钉的一根船钉，他记得。', ARRAY['渡海船工', '田产丈量员'], ARRAY['1066年那支舰队，有你钉的一根船钉，他记得。', '《末日审判书》里，你替他丈量了半个英格兰的田产。']),
  (65, '亨利八世', 'Henry VIII', '1491—1547', '16世纪', '英格兰', '国王', ARRAY['帝王', '英格兰', '宗教'], '英格兰国王，以六次婚姻与宗教改革著称。他瓦解英国教会与罗马的联系，自任教会最高首脑。', '六宴掌勺', '', 'assets/figures/henry8.jpg', ARRAY['06-28', '06-24'], ARRAY['诞辰 · 1491年6月28日', '加冕 · 1509年6月24日'], ARRAY['birth', 'throne'], '他六场婚宴，厨房调度都归你，菜单你拍板。', ARRAY['六宴掌勺', '教会文书'], ARRAY['他六场婚宴，厨房调度都归你，菜单你拍板。', '教会易主那些文书，署名的是你，他只管盖印。']),
  (66, '西塞罗', 'Cicero', '前106—前43', '古罗马', '罗马', '演说家', ARRAY['政治家', '罗马', '哲学'], '古罗马政治家、演说家与哲学家。他以雄辩捍卫共和，书信与论著成为拉丁文学典范，影响后世修辞与政治思想。', '演说提词', '', 'assets/figures/cicero.jpg', ARRAY['01-03', '08-01'], ARRAY['诞辰 · 前106年1月3日', '任执政官 · 前63年'], ARRAY['birth', 'event'], '他上台前，稿子最后一遍由你过目，错处你先圈。', ARRAY['演说提词', '别墅园丁'], ARRAY['他上台前，稿子最后一遍由你过目，错处你先圈。', '他在图斯库鲁姆的园子，你替他打理了十几年。']),
  (67, '伯里克利', 'Pericles', '约前495—前429', '古希腊', '雅典', '政治家', ARRAY['政治家', '希腊', '民主'], '雅典政治家，伯里克利时代的核心人物。他推动民主、赞助艺术与建筑，使雅典进入黄金时期。', '卫城石匠', '', 'assets/figures/pericles.jpg', ARRAY['09-01', '04-01'], ARRAY['诞辰 · 约前495年', '伯罗奔尼撒战争爆发 · 前431年'], ARRAY['birth', 'event'], '帕特农神庙的石头，你亲手凿过一块，他常来摸那道缝。', ARRAY['卫城石匠', '公民大会传令'], ARRAY['帕特农神庙的石头，你亲手凿过一块，他常来摸那道缝。', '公民大会散场，是你替他向人群传最后的口谕。']),
  (68, '托马斯·杰斐逊', 'Thomas Jefferson', '1743—1826', '18—19世纪', '美国', '总统', ARRAY['政治家', '美国', '启蒙'], '美国第三任总统，《独立宣言》主要起草人。他主张天赋人权与有限政府，也是一位博学的建筑师与发明家。', '宣言抄写', '', 'assets/figures/jefferson.jpg', ARRAY['04-13', '07-04'], ARRAY['诞辰 · 1743年4月13日', '《独立宣言》通过 · 1776年7月4日'], ARRAY['birth', 'event'], '《独立宣言》的初稿，誊抄出自你手，墨迹未干他就取走了。', ARRAY['宣言抄写', '庄园建筑师'], ARRAY['《独立宣言》的初稿，誊抄出自你手，墨迹未干他就取走了。', '蒙蒂塞洛的那座房子，草图你帮他改过好几回。']),
  (69, '本杰明·富兰克林', 'Benjamin Franklin', '1706—1790', '18世纪', '美国', '科学家 · 外交家', ARRAY['科学家', '美国', '政治'], '美国开国元勋、科学家与外交家。他揭示雷电本质、发明避雷针，参与起草独立宣言，并在英法间纵横捭阖。', '风筝助手', '', 'assets/figures/benfranklin.jpg', ARRAY['01-17', '09-03'], ARRAY['诞辰 · 1706年1月17日', '巴黎和约 · 1783年9月3日'], ARRAY['birth', 'event'], '那个雷雨天的风筝，线攥在你手里，雷声一响你先松了手。', ARRAY['风筝助手', '外交信使'], ARRAY['那个雷雨天的风筝，线攥在你手里，雷声一响你先松了手。', '巴黎那些密信，往来都经你手，封蜡的印你替他按。']),
  (70, '奥托·冯·俾斯麦', 'Otto von Bismarck', '1815—1898', '19世纪', '普鲁士', '宰相', ARRAY['政治家', '德国', '统一'], '普鲁士首相，德意志统一的设计师。他以现实政治纵横捭阖，于1871年建立德意志帝国并任首任宰相。', '铁血书记', '', 'assets/figures/bismarck.jpg', ARRAY['04-01', '01-18'], ARRAY['诞辰 · 1815年4月1日', '德意志帝国建立 · 1871年1月18日'], ARRAY['birth', 'event'], '他口述的电报，你一字不落记下来，连他的冷笑话也记。', ARRAY['铁血书记', '宰相府门房'], ARRAY['他口述的电报，你一字不落记下来，连他的冷笑话也记。', '宰相府的门，你拦过不少想硬闯的人，唯独放你进。'])
